import json

# Try a DIFFERENT scan order - row by row, within each row check left, then interior cols, then right
test_in = G['Test input']
demo_in = G['Demo pair 1 input']

def find_first_gap(grid):
    h, w = len(grid), len(grid[0])
    positions_4 = [(r, c) for r in range(h) for c in range(w) if grid[r][c] == 4]

    if not positions_4:
        return None

    min_r = min(p[0] for p in positions_4)
    max_r = max(p[0] for p in positions_4)
    min_c = min(p[1] for p in positions_4)
    max_c = max(p[1] for p in positions_4)

    # Scan row by row
    for r in range(min_r, max_r + 1):
        # If this is an interior row, check left and right only
        if r > min_r and r < max_r:
            if grid[r][min_c] != 4:
                return (r, min_c)
            if grid[r][max_c] != 4:
                return (r, max_c)
        else:
            # Top or bottom row - check all columns
            for c in range(min_c, max_c + 1):
                if grid[r][c] != 4:
                    return (r, c)

    return None

print("Testing with DEMO INPUT:")
gap_demo = find_first_gap(demo_in)
print(f"  First gap: {gap_demo}")

print("\nTesting with TEST INPUT:")
gap_test = find_first_gap(test_in)
print(f"  First gap: {gap_test}")

# Fill and print expected output
if gap_test:
    expected_out = [row[:] for row in test_in]
    expected_out[gap_test[0]][gap_test[1]] = 2
    print("\nExpected output:")
    print(json.dumps(expected_out))

