    # Scan row by row
    for r in range(min_r, max_r + 1):
        is_top_bottom = (r == min_r or r == max_r)

        if is_top_bottom:
            print(f"  Checking row {r} (top/bottom), cols {min_c} to {max_c}:")
            for c in range(min_c, max_c + 1):
                val = grid[r][c]
                status = "✓" if val == 4 else f"✗ ({val})"
                print(f"    col {c}: {status}")
                if val != 4:
                    return (r, c)
        else:
            print(f"  Checking row {r} (interior), left={grid[r][min_c]}, right={grid[r][max_c]}:")
            if grid[r][min_c] != 4:
                return (r, min_c)
            if grid[r][max_c] != 4:
                return (r, max_c)

    return None

print("DEBUGGING TEST INPUT:")
gap = debug_find_first_gap(test_in)
